export interface ISpinnerService {
    show(...args: any[]): void;
    hide(...args: any[]): void;
    showAsync(...args: any[]): Promise<void>;
    hideAsync(...args: any[]): Promise<void>;
    setDelay(seconds: number): void;
}

export class NullSpinner implements ISpinnerService {
    show(...args: any[]) { }
    hide(...args: any[]) { }
    showAsync(...args: any[]) {
        return new Promise((resolve, reject) => {
            resolve();
        }) as Promise<void>;
    }
    hideAsync(...args: any[]) {
        return new Promise((resolve, reject) => {
            resolve();
        }) as Promise<void>;
    }
    setDelay(seconds: number) { }
}
