import { ISpinnerService, NullSpinner } from './spinner.interface';

export interface ISpinnerServiceExt extends ISpinnerService {
    startToListenSpinner(...args: any[]): void;
    stopListener(...args: any[]): void;
}

export class NullSpinnerExt extends NullSpinner implements ISpinnerServiceExt {
    public startToListenSpinner(...args: any[]) {
    }

    public stopListener(...args: any[]) {
    }
}

/* Note that on purpose we do not make this to be service.
 * Therefore, we are able to define its behavior in the host application. */
export class SpinnerProviderImpl {

    private readonly _impl: ISpinnerServiceExt;

    constructor() {
        this._impl = new NullSpinnerExt();
    }

    get(key: string): ISpinnerServiceExt {
        return this._impl;
    }
}


